    const err = checkLink({ ...graph, edges: [] }, catalog, {
      from: e.from, to: e.to, from_pin: e.from_pin ?? "", to_pin: e.to_pin ?? "",
    });
    if (err) messages.push(`Erreur : lien ${e.from} → ${e.to} invalide. ${err}`);
  }
  return messages;
}

