"use client";

import "@xyflow/react/dist/style.css";

import {
  Background,
  BackgroundVariant,
  Controls,
  ReactFlow,
  applyEdgeChanges,
  applyNodeChanges,
  type Connection,
  type Edge,
  type EdgeChange,
  type Node,
  type NodeChange,
  type ReactFlowInstance,
} from "@xyflow/react";
import { useCallback, useMemo, useRef, useState } from "react";

import { buildFlow, nodeTypes } from "@/components/blueprint-canvas";
import { pinColor } from "@/lib/blueprint-style";
import {
  addLink,
  checkLink,
  type Link,
  compileGraph,
  filterPalette,
  normalizeGraph,
} from "@/lib/graph-editing";
import type { CatalogNode, GraphNode, NormalizedGraph } from "@/lib/node-catalog";

const extra = (g?: GraphNode) => ({ gtype: g?.type, glabel: g?.label, gprops: g?.properties });

type Props = {
  graph: NormalizedGraph;
  catalog: CatalogNode[];
  /** Types autorisés par l'exercice ; null = tout le catalogue. */
  palette?: string[] | null;
  lockedNodeIds?: string[];
  onChange?: (graph: NormalizedGraph) => void;
};

/** Canvas d'édition : ajout par clic droit, liens, suppression, compilation locale. */
export default function BlueprintEditor({
  graph, catalog, palette = null, lockedNodeIds = [], onChange,
}: Props) {
  const locked = useMemo(() => new Set(lockedNodeIds), [lockedNodeIds]);
  const initial = useMemo(() => {
    const flow = buildFlow(graph, catalog);
    const nodes = flow.nodes.map((n) => ({
      ...n,
      draggable: !locked.has(n.id),
      deletable: !locked.has(n.id),
      data: { ...n.data, ...extra(graph.nodes.find((g) => g.id === n.id)) },
    }));
    return { nodes: nodes as Node[], edges: flow.edges };
  }, [graph, catalog, locked]);

  const [nodes, setNodes] = useState<Node[]>(initial.nodes);
  const [edges, setEdges] = useState<Edge[]>(initial.edges);
  const [menu, setMenu] = useState<{ x: number; y: number; fx: number; fy: number } | null>(null);
  const [query, setQuery] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [compiled, setCompiled] = useState<string[] | null>(null);
  const flowRef = useRef<ReactFlowInstance | null>(null);
  const counter = useRef(0);

  const toGraph = useCallback(
    (ns: Node[], es: Edge[]): NormalizedGraph =>
      normalizeGraph({
        nodes: ns.map((n) => ({
          id: n.id, type: String(n.data.gtype), position: n.position,
          ...(n.data.glabel ? { label: n.data.glabel as string } : {}),
          ...(n.data.gprops ? { properties: n.data.gprops as Record<string, unknown> } : {}),
        })),
        edges: es.map((e) => ({
          from: e.source, to: e.target,
          from_pin: e.sourceHandle ?? undefined, to_pin: e.targetHandle ?? undefined,
        })),
      }),
    [],
  );
  const commit = (ns: Node[], es: Edge[]) => {
    setNodes(ns);
    setEdges(es);
    onChange?.(toGraph(ns, es));
  };

  const onNodesChange = (changes: NodeChange[]) => {
    // Un node verrouillé ne se supprime pas (le serveur le revérifie).
    const safe = changes.filter((c) => !(c.type === "remove" && locked.has(c.id)));
    commit(applyNodeChanges(safe, nodes), edges);
  };
  const onEdgesChange = (changes: EdgeChange[]) => commit(nodes, applyEdgeChanges(changes, edges));

  const onConnect = (c: Connection) => {
    const link = {
      from: c.source, to: c.target, from_pin: c.sourceHandle ?? "", to_pin: c.targetHandle ?? "",
    };
    const current = toGraph(nodes, edges);
    const error = checkLink(current, catalog, link);
    if (error) return setMessage(error);
    setMessage(null);
    const next = addLink(current, catalog, link);
    const type = catalog
      .find((n) => n.id === current.nodes.find((x) => x.id === link.from)?.type)
      ?.pins.find((p) => p.name === link.from_pin)?.type ?? "";
    const same = (e: Edge, l: Link) =>
      e.source === l.from && e.target === l.to && e.sourceHandle === l.from_pin && e.targetHandle === l.to_pin;
    // Les liens existants gardent leur style ; une entrée de données remplacée disparaît.
    const kept = edges.filter((e) =>
      next.edges.some((x) => same(e, { from: x.from, to: x.to, from_pin: x.from_pin ?? "", to_pin: x.to_pin ?? "" })));
    const es: Edge[] = [...kept, {
      id: `l${++counter.current}-${link.from}-${link.to}-${link.to_pin}`,
      source: link.from, target: link.to, sourceHandle: link.from_pin, targetHandle: link.to_pin,
      style: { stroke: pinColor(type), strokeWidth: 2 },
    }];
    commit(nodes, es);
  };

  const addNode = (def: CatalogNode) => {
    if (!menu) return;
    counter.current += 1;
    const node: Node = {
      id: `new_${counter.current}`,
      type: "blueprint",
      position: { x: menu.fx, y: menu.fy },
      data: { title: def.label, definition: def, ...extra({ id: "", type: def.id }) },
    };
    commit([...nodes, node], edges);
    setMenu(null);
    setQuery("");
  };

  const results = filterPalette(catalog, palette, query);

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-3">
        <button
          type="button"
          className="rounded bg-accent px-3 py-1 text-sm font-semibold text-white"
          onClick={() => setCompiled(compileGraph(toGraph(nodes, edges), catalog))}
        >
          Compiler
        </button>
        {message && <p role="alert" className="text-sm text-red-400">{message}</p>}
      </div>
      <div
        role="region"
        aria-label="Canvas Blueprint (édition)"
        className="relative h-[28rem] w-full overflow-hidden rounded border border-border-subtle bg-surface-0"
      >
        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onInit={(i) => (flowRef.current = i)}
          onPaneContextMenu={(e) => {
            e.preventDefault();
            const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
            const f = flowRef.current?.screenToFlowPosition({ x: e.clientX, y: e.clientY });
            setMenu({
              x: e.clientX - rect.left, y: e.clientY - rect.top,
              fx: f?.x ?? e.clientX - rect.left, fy: f?.y ?? e.clientY - rect.top,
            });
          }}
          onPaneClick={() => setMenu(null)}
          deleteKeyCode={["Delete", "Backspace"]}
          fitView
          minZoom={0.2}
          maxZoom={2}
          colorMode="dark"
          proOptions={{ hideAttribution: true }}
        >
          <Background variant={BackgroundVariant.Lines} gap={24} color="#1b2130" />
          <Controls showInteractive={false} />
        </ReactFlow>
        {menu && (
          <div
            role="dialog"
            aria-label="Ajouter un node"
            className="absolute z-10 w-64 rounded border border-border-subtle bg-surface-1 p-2 shadow-lg"
            style={{ left: menu.x, top: menu.y }}
          >
            <input
              autoFocus
              aria-label="Rechercher un node"
              placeholder="Rechercher un node..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="mb-1 w-full rounded bg-surface-0 px-2 py-1 text-sm"
            />
            <ul className="max-h-48 overflow-y-auto" role="listbox">
              {results.map((def) => (
                <li key={def.id}>
                  <button
                    type="button"
                    role="option"
                    aria-selected={false}
                    className="w-full px-2 py-1 text-left text-sm hover:bg-surface-0"
                    onClick={() => addNode(def)}
                  >
                    {def.label}
                  </button>
                </li>
              ))}
              {results.length === 0 && (
                <li className="px-2 py-1 text-sm text-content-muted">Aucun node trouvé.</li>
              )}
            </ul>
          </div>
        )}
      </div>
      {compiled && (
        <ul role="status" aria-label="Résultat de la compilation" className="text-sm">
          {compiled.length === 0 ? (
            <li className="text-green-400">Compilation réussie : aucune erreur locale.</li>
          ) : (
            compiled.map((m) => <li key={m} className="text-red-400">{m}</li>)
          )}
        </ul>
      )}
    </div>
  );
}
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeAll, describe, expect, it, vi } from "vitest";

import BlueprintEditor from "@/components/blueprint-editor";
import { addLink, checkLink, compileGraph, filterPalette, normalizeGraph } from "@/lib/graph-editing";
import type { CatalogNode, NormalizedGraph } from "@/lib/node-catalog";

beforeAll(() => {
  vi.stubGlobal("ResizeObserver", class { observe() {} unobserve() {} disconnect() {} });
  vi.stubGlobal("DOMMatrixReadOnly", class { m22 = 1; });
});

const catalog: CatalogNode[] = [
  { id: "Begin", label: "Event BeginPlay", category: "events",
    pins: [{ name: "then", label: "", direction: "output", type: "exec" }] },
  { id: "Print", label: "Print String", category: "functions",
    pins: [
      { name: "execute", label: "", direction: "input", type: "exec" },
      { name: "InString", label: "In String", direction: "input", type: "string" },
      { name: "then", label: "", direction: "output", type: "exec" },
    ] },
  { id: "Str", label: "Make Literal String", category: "functions",
    pins: [{ name: "Value", label: "", direction: "output", type: "string" }] },
];
const graph: NormalizedGraph = {
  nodes: [{ id: "n1", type: "Begin" }, { id: "n2", type: "Print" }, { id: "n3", type: "Str" }],
  edges: [],
};
const link = (from: string, to: string, from_pin: string, to_pin: string) => ({ from, to, from_pin, to_pin });

const pressDelete = () => {
  fireEvent.keyDown(document.body, { key: "Delete", code: "Delete" });
  fireEvent.keyUp(document.body, { key: "Delete", code: "Delete" });
};

describe("édition du graphe", () => {
  it("ajoute un node via le menu de clic droit, filtré par la palette", () => {
    const onChange = vi.fn();
    render(<BlueprintEditor graph={{ nodes: [], edges: [] }} catalog={catalog} palette={["Print"]} onChange={onChange} />);
    fireEvent.contextMenu(document.querySelector(".react-flow__pane")!);
    expect(screen.queryByText("Event BeginPlay")).toBeNull();
    fireEvent.click(screen.getByRole("option", { name: "Print String" }));
    expect(onChange).toHaveBeenLastCalledWith(
      expect.objectContaining({ nodes: [expect.objectContaining({ type: "Print" })] }),
    );
    expect(screen.getByText("Print String")).toBeInTheDocument();
  });

  it("filtre le catalogue par texte sans palette", () => {
    expect(filterPalette(catalog, null, "string").map((n) => n.id)).toEqual(["Print", "Str"]);
  });

  it("accepte un lien valide et le normalise", () => {
    const l = link("n1", "n2", "then", "execute");
    expect(checkLink(graph, catalog, l)).toBeNull();
    const next = addLink(graph, catalog, l);
    expect(normalizeGraph(next).edges).toEqual([l]);
  });

  it("refuse les liens incohérents avec un message clair", () => {
    expect(checkLink(graph, catalog, link("n2", "n1", "then", "then"))).toMatch(/sortie à une entrée/);
    expect(checkLink(graph, catalog, link("n1", "n2", "then", "InString"))).toMatch(/exécution.*données/);
    expect(checkLink(graph, catalog, link("n2", "n2", "then", "execute"))).toMatch(/lui-même/);
    const wrong: CatalogNode[] = catalog.map((n) =>
      n.id === "Str" ? { ...n, pins: [{ name: "Value", label: "", direction: "output" as const, type: "int" }] } : n);
    expect(checkLink(graph, wrong, link("n3", "n2", "Value", "InString"))).toMatch(/incompatibles/);
  });

  it("supprime un node libre mais jamais un node verrouillé", async () => {
    const onChange = vi.fn();
    render(<BlueprintEditor graph={graph} catalog={catalog} lockedNodeIds={["n1"]} onChange={onChange} />);
    const ids = () => onChange.mock.lastCall?.[0].nodes.map((n: { id: string }) => n.id);
    fireEvent.click(document.querySelector('[data-id="n1"]')!);
    pressDelete();
    await new Promise((r) => setTimeout(r, 50));
    expect(document.querySelector('[data-id="n1"]')).not.toBeNull();
    expect(ids() ?? ["n1"]).toContain("n1");
    fireEvent.click(document.querySelector('[data-id="n2"]')!);
    pressDelete();
    await waitFor(() => expect(document.querySelector('[data-id="n2"]')).toBeNull());
    expect(ids()).toEqual(expect.arrayContaining(["n1", "n3"]));
    expect(ids()).not.toContain("n2");
  });

  it("conserve properties et label des nodes de départ dans la sortie", () => {
    const onChange = vi.fn();
    const start: NormalizedGraph = {
      nodes: [{ id: "n1", type: "Begin", label: "Début", properties: { variable: "Health" } }],
      edges: [],
    };
    render(<BlueprintEditor graph={start} catalog={catalog} palette={["Print"]} onChange={onChange} />);
    fireEvent.contextMenu(document.querySelector(".react-flow__pane")!);
    fireEvent.click(screen.getByRole("option", { name: "Print String" }));
    expect(onChange.mock.lastCall?.[0].nodes[0]).toEqual(
      expect.objectContaining({ id: "n1", label: "Début", properties: { variable: "Health" } }),
    );
  });

  it("compile localement et signale les nodes jamais exécutés", () => {
    expect(compileGraph(graph, catalog).join()).toMatch(/Print String ne sera jamais exécuté/);
    render(<BlueprintEditor graph={graph} catalog={catalog} />);
    fireEvent.click(screen.getByRole("button", { name: "Compiler" }));
    expect(screen.getByRole("status")).toHaveTextContent(/jamais exécuté/);
  });
});
